/* 
  This function takes accepts a Directus Flow data object and formats it into a proper activity object.
  @param {object} data - The Directus Flow data object
  @returns {object} - The formatted activity object
*/
function formatActivity(data) {
  const trigger = data.$trigger;
  const acct = data.$accountability;

  const {
    activity_type,
    start_date,
    name,
    activity_notes,
    is_completed,
    collection,
    keys,
  } = trigger.body;

  // Default the owner of the activity to the user who created the activity
  const owner = acct.user;

  const formattedActivity = {
    activity_type,
    start_date,
    name,
    activity_notes,
    is_completed,
    owner,
  };

  switch (collection) {
    case "contacts":
      // Contacts is a many to many relationship, so we need to format the keys as an array of objects
      formattedActivity.contacts = keys.map((key) => ({ contact: key }));
      break;
    case "organizations":
      formattedActivity.organization = keys[0];
      break;
    case "deals":
      formattedActivity.deal = keys[0];
      break;
    default:
      throw new Error(`Unsupported collection type: ${collection}`);
  }

  return formattedActivity;
}

module.exports = function (data) {
  return formatActivity(data);
};

/*
  Builds the email and the activity log entry for the Send Email flow.
  Recipients come from the "To" field, or default to the contact (or the deal's contacts) when it's left blank.
*/
module.exports = function (data) {
  const { collection, keys, to, subject, body } = data.$trigger.body;

  if (collection === 'deals' && keys.length !== 1) {
    throw new Error('Run Send Email from one deal at a time.');
  }

  // The read returns contacts matching either the selected contacts or the selected deal, so keep only the ones for this collection
  const rows = Array.isArray(data.read_contacts) ? data.read_contacts : [data.read_contacts].filter(Boolean);
  const contacts = rows.filter((contact) =>
    collection === 'contacts'
      ? keys.includes(contact.id)
      : (contact.deals || []).some((link) => keys.includes(link.deal)),
  );

  const typed = (Array.isArray(to) ? to : String(to || '').split(','))
    .map((email) => email.trim())
    .filter(Boolean);

  const recipients = typed.length ? typed : contacts.map((contact) => contact.email).filter(Boolean);
  const uniqueRecipients = [...new Set(recipients.map((email) => email.toLowerCase()))];

  if (!uniqueRecipients.length) {
    throw new Error('No recipients. Add an address in "To" or give the contact an email address.');
  }

  // From a contact, always link that contact. From a deal, link the deal's contacts who got the email.
  const linkedContacts =
    collection === 'contacts'
      ? contacts
      : contacts.filter((contact) => contact.email && uniqueRecipients.includes(contact.email.toLowerCase()));
  const now = new Date().toISOString();

  // activities.name is varchar(255)
  const name = `Email: ${subject}`;

  const activity = {
    name: name.length > 255 ? `${name.slice(0, 254)}…` : name,
    activity_type: 'email',
    activity_notes: body,
    start_date: now,
    is_completed: true,
    date_completed: now,
    owner: data.$accountability.user,
    contacts: linkedContacts.map((contact) => ({ contact: contact.id })),
  };

  if (collection === 'deals') activity.deal = keys[0];

  // One message per recipient, so contacts on a deal don't see each other's addresses
  const messages = uniqueRecipients.map((recipient) => ({ to: recipient, subject, body }));

  return { to: uniqueRecipients, messages, subject, body, activity };
};
